// 其余核心节点：每个节点一题概念辨析，以及一题带给定数据的计算或读图判断。
// 选项的第一个值是经核对的答案；其余值是针对常见误解的干扰项。
function choiceQuestion(nodeId, kind, prompt, choices, explanation) {
  const id = `${nodeId}-${kind}`;
  const offset = [...id].reduce((sum, character) => sum + character.codePointAt(0), 0) % choices.length;
  const ordered = [...choices.slice(offset), ...choices.slice(0, offset)];
  questions.push({ id, nodeId, version: 1, kind, prompt,
    options: ordered.map((text, index) => ({ id: String(index), text })),
    answer: String((choices.length - offset) % choices.length), explanation });
}
function concept(nodeId, prompt, choices, explanation) {
  choiceQuestion(nodeId, 'concept', prompt, choices, explanation);
}
function interpret(nodeId, prompt, choices, explanation) {
  choiceQuestion(nodeId, 'interpretation', prompt, choices, explanation);
}
function numeric(nodeId, prompt, answer, unit, explanation, absolute = 0.01) {
  questions.push({ id: `${nodeId}-numeric`, nodeId, version: 1, kind: 'numeric', prompt,
    answer, unit, tolerance: { absolute, relative: 0 }, explanation });
}

